/**
 * frontend/src/components/CameraRecognition.jsx
 * 🔥 VERSION ULTIMATE INDUSTRIAL - PERSISTENT VIDEO DOM FIX
 */

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

// ============ CONFIGURATION DE PRODUCTION ============
const CAPTURE_INTERVAL_DEFAULT = 1500;
const CAPTURE_INTERVAL_MIN = 800;
const SUCCESS_PAUSE_MS = 3000;
const DUPLICATE_CACHE_MS = 5000;
const UI_REFRESH_RATE = 15;

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS (ÉTAT INTERNE & LOCKS) ============
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const timeoutRef = useRef(null);

  const autoModeRef = useRef(false);
  const processingRef = useRef(false);
  const loopRunningRef = useRef(false);
  const abortControllerRef = useRef(null);

  const frameCountRef = useRef(0);
  const lastSuccessIdRef = useRef(null);
  const lastSuccessTimeRef = useRef(0);
  const adaptiveIntervalRef = useRef(CAPTURE_INTERVAL_DEFAULT);

  // ============ STATES (UI UNIQUEMENT) ============
  const [autoMode, setAutoMode] = useState(false);
  const [cameraActive, setCameraActive] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastResult, setLastResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [successCount, setSuccessCount] = useState(0);
  const [frameCountUI, setFrameCountUI] = useState(0);

  useEffect(() => {
    autoModeRef.current = autoMode;
  }, [autoMode]);

  /**
   * 🛠 UTILITAIRE : Conversion Canvas vers Base64 via Blob (Non-bloquant)
   */
  const getBase64FromCanvas = (canvas) => {
    return new Promise((resolve) => {
      canvas.toBlob((blob) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.readAsDataURL(blob);
      }, 'image/jpeg', 0.8);
    });
  };

  /**
   * ✅ DÉMARRER CAMÉRA (Logique Imposée + Persistance DOM)
   */
  const startCamera = async () => {
    try {
      console.log("🎥 Starting camera...");
      setError(null);
      setLoading(true);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false
      });

      streamRef.current = stream;
      const video = videoRef.current;

      if (!video) throw new Error("Video element not found");

      // 🔥 IMPORTANT: assigner stream au tag déjà présent dans le DOM
      video.srcObject = stream;

      // 🔥 FORCER play immédiatement
      await video.play().catch((err) => {
        console.warn("Play blocked, retrying...", err);
      });

      // Fallback sécurité
      video.onloadeddata = async () => {
        try {
          await video.play();
        } catch (e) {
          console.error("SECOND PLAY FAIL:", e);
        }
      };

      setCameraActive(true);
      setLoading(false);
      setAutoMode(true);
      startCaptureLoop();

      if (addNotification) addNotification("✅ Caméra active", "success");
      console.log("🎥 CAMERA READY");

    } catch (err) {
      console.error("❌ CAMERA ERROR:", err);
      setError(err.message || "Camera error");
      setLoading(false);
    }
  };

  /**
   * 🔄 BOUCLE DE CAPTURE (Anti-Spam & Mutex)
   */
  const startCaptureLoop = () => {
    if (loopRunningRef.current) return;
    loopRunningRef.current = true;
    captureFrame();
  };

  const captureFrame = async () => {
    if (!autoModeRef.current || !streamRef.current || !videoRef.current) {
      loopRunningRef.current = false;
      return;
    }

    if (processingRef.current || videoRef.current.readyState < 2) {
      scheduleNext(200);
      return;
    }

    processingRef.current = true;

    try {
      const canvas = canvasRef.current;
      const video = videoRef.current;

      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d', { alpha: false });
      ctx.drawImage(video, 0, 0);

      const imageBase64 = await getBase64FromCanvas(canvas);

      frameCountRef.current++;
      if (frameCountRef.current % UI_REFRESH_RATE === 0) setFrameCountUI(frameCountRef.current);

      await processFrame(imageBase64);
    } catch (err) {
      scheduleNext(adaptiveIntervalRef.current);
    } finally {
      processingRef.current = false;
    }
  };

  const processFrame = async (imageBase64) => {
    const startTime = Date.now();
    try {
      abortControllerRef.current = new AbortController();
      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      const latency = Date.now() - startTime;
      if (latency > 2000) adaptiveIntervalRef.current = Math.min(adaptiveIntervalRef.current + 500, 4000);
      else adaptiveIntervalRef.current = Math.max(adaptiveIntervalRef.current - 100, CAPTURE_INTERVAL_MIN);

      if (data?.success && data?.student) {
        handleResultSuccess(data, imageBase64);
        scheduleNext(SUCCESS_PAUSE_MS);
      } else {
        handleResultFailure(data, imageBase64);
        scheduleNext(adaptiveIntervalRef.current);
      }
    } catch (err) {
      scheduleNext(3000);
    }
  };

  const handleResultSuccess = (data, imageBase64) => {
    const now = Date.now();
    const isDuplicate = lastSuccessIdRef.current === data.student && (now - lastSuccessTimeRef.current) < DUPLICATE_CACHE_MS;

    setCapturedImage(imageBase64);
    setSuccessCount(prev => prev + 1);
    setLastResult({
      success: true,
      student: data.student,
      confidence: (data.confidence * 100).toFixed(1),
      timestamp: new Date().toLocaleTimeString(),
      message: `✅ ${data.student}`
    });

    if (!isDuplicate) {
      if (addNotification) addNotification(`✅ Bienvenue ${data.student}`, 'success');
      lastSuccessIdRef.current = data.student;
      lastSuccessTimeRef.current = now;
    }
  };

  const handleResultFailure = (data, imageBase64) => {
    setCapturedImage(imageBase64);
    const conf = data?.confidence ? (data.confidence * 100).toFixed(1) : 0;
    setLastResult({
      success: false,
      student: 'Inconnu',
      message: conf > 40 ? '⚠️ Confiance faible' : '❌ Non reconnu',
      confidence: conf,
      timestamp: new Date().toLocaleTimeString()
    });
  };

  const scheduleNext = (delay) => {
    if (!autoModeRef.current) return;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(captureFrame, delay);
  };

  const closeCamera = useCallback(() => {
    autoModeRef.current = false;
    loopRunningRef.current = false;
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    if (abortControllerRef.current) abortControllerRef.current.abort();
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    setCameraActive(false);
    setAutoMode(false);
    setLoading(false);
    if (videoRef.current) videoRef.current.srcObject = null;
  }, []);

  useEffect(() => { return () => closeCamera(); }, [closeCamera]);

  // ============ RENDU UI ============
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Reconnaissance Industrielle</h1>
          <p style={styles.subtitle}>{cameraActive ? (autoMode ? '🔄 Analyse en cours' : '⏸ Pause') : 'Prêt à démarrer'}</p>
        </div>

        {/* ✅ CORRECT: Le tag video est TOUJOURS présent dans le DOM */}
        <div style={styles.videoWrapper}>
          <video 
            ref={videoRef} 
            autoPlay 
            muted 
            playsInline 
            style={{ ...styles.video, display: cameraActive ? 'block' : 'none' }} 
          />
          {!cameraActive && (
            <div style={styles.videoPlaceholder}>
              <p style={styles.placeholderText}>📹 Caméra inactive</p>
            </div>
          )}
          {cameraActive && autoMode && <div style={styles.scanBadge}>🔄 SCANNING</div>}
        </div>

        <div style={styles.controls}>
          {!cameraActive ? (
            <button onClick={startCamera} disabled={loading} style={{ ...styles.btn, ...styles.btnSuccess }}>
              {loading ? '⏳ Chargement...' : '▶️ Démarrer Caméra'}
            </button>
          ) : (
            <>
              {autoMode ? (
                <button onClick={() => setAutoMode(false)} style={{ ...styles.btn, ...styles.btnWarning }}>⏸ Pause</button>
              ) : (
                <button onClick={() => { setAutoMode(true); startCaptureLoop(); }} style={{ ...styles.btn, ...styles.btnSuccess }}>▶️ Reprendre</button>
              )}
              <button onClick={closeCamera} style={{ ...styles.btn, ...styles.btnDanger }}>🛑 Éteindre</button>
            </>
          )}
        </div>

        {error && <div style={styles.errorBox}>{error}</div>}

        {lastResult && (
          <div style={{ ...styles.resultBox, borderLeftColor: lastResult.success ? COLORS.success : COLORS.warning }}>
            <h2 style={styles.resultTitle}>{lastResult.message}</h2>
            <div style={styles.imagesGrid}>
              <div style={styles.imageBox}>
                {capturedImage && <img src={capturedImage} alt="Face" style={styles.image} />}
              </div>
              <div style={styles.infoBox}>
                <div style={styles.detailRow}><span>👤 Nom:</span><b>{lastResult.student}</b></div>
                <div style={styles.detailRow}><span>🎯 Confiance:</span><b>{lastResult.confidence}%</b></div>
                <div style={styles.detailRow}><span>🕒 Heure:</span><span>{lastResult.timestamp}</span></div>
              </div>
            </div>
          </div>
        )}

        <div style={styles.debugBox}>
          <div style={styles.debugGrid}>
            <div><span style={styles.debugLabel}>✅ Succès</span><span style={styles.debugValue}>{successCount}</span></div>
            <div><span style={styles.debugLabel}>📹 Frames</span><span style={styles.debugValue}>{frameCountUI}</span></div>
            <div><span style={styles.debugLabel}>⏱ Latence</span><span style={styles.debugValue}>{adaptiveIntervalRef.current}ms</span></div>
          </div>
        </div>
      </div>
      <canvas ref={canvasRef} style={{ display: 'none' }} />
    </div>
  );
};

const styles = {
  container: { padding: '20px', maxWidth: '1000px', margin: '0 auto', backgroundColor: COLORS.background, minHeight: '100vh', fontFamily: 'Inter, sans-serif' },
  card: { backgroundColor: COLORS.surface, borderRadius: '20px', padding: '30px', boxShadow: '0 10px 30px rgba(0,0,0,0.08)' },
  header: { textAlign: 'center', marginBottom: '20px' },
  title: { fontSize: '1.8rem', fontWeight: '800', color: COLORS.textMain, margin: '0' },
  subtitle: { color: COLORS.textMuted, marginTop: '5px' },
  videoWrapper: { position: 'relative', width: '100%', paddingBottom: '56.25%', backgroundColor: '#000', borderRadius: '15px', overflow: 'hidden', marginBottom: '20px' },
  video: { position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', objectFit: 'cover' },
  videoPlaceholder: { position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#1e293b' },
  placeholderText: { color: '#fff', fontSize: '1.2rem' },
  scanBadge: { position: 'absolute', top: '15px', right: '15px', backgroundColor: COLORS.primary, color: 'white', padding: '8px 12px', borderRadius: '6px', fontWeight: 'bold' },
  controls: { display: 'flex', gap: '10px', marginBottom: '20px' },
  btn: { flex: 1, padding: '12px', border: 'none', borderRadius: '10px', fontWeight: '600', cursor: 'pointer' },
  btnSuccess: { backgroundColor: COLORS.success, color: 'white' },
  btnWarning: { backgroundColor: COLORS.warning, color: 'white' },
  btnDanger: { backgroundColor: 'transparent', border: `2px solid ${COLORS.danger}`, color: COLORS.danger },
  errorBox: { padding: '12px', backgroundColor: '#FEE2E2', color: '#991B1B', borderRadius: '8px', marginBottom: '15px' },
  resultBox: { backgroundColor: COLORS.background, padding: '20px', borderRadius: '15px', marginBottom: '20px', borderLeft: '5px solid' },
  resultTitle: { fontSize: '1.1rem', margin: '0 0 15px 0' },
  imagesGrid: { display: 'grid', gridTemplateColumns: '120px 1fr', gap: '20px' },
  imageBox: { width: '120px', height: '90px', backgroundColor: '#ddd', borderRadius: '8px', overflow: 'hidden' },
  image: { width: '100%', height: '100%', objectFit: 'cover' },
  infoBox: { display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: '5px' },
  detailRow: { display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem' },
  debugBox: { borderTop: `1px solid ${COLORS.border}`, paddingTop: '15px' },
  debugGrid: { display: 'flex', justifyContent: 'space-between' },
  debugLabel: { fontSize: '0.7rem', color: COLORS.textMuted, display: 'block' },
  debugValue: { fontWeight: 'bold', color: COLORS.primary }
};

export default CameraRecognition;
